-- Contract facts become reviewed inputs or cumulative obligations, never both.
-- No old contract, attachment, payroll profile or confirmed wage is updated.
CREATE TABLE ty_cp_resolution(
 id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 group_id bigint NOT NULL REFERENCES ty_group(id),company_id bigint NOT NULL REFERENCES ty_company(id),
 person_id bigint NOT NULL REFERENCES ty_person(id),employment_id bigint NOT NULL REFERENCES ty_employment(id),
 term_period_id bigint NOT NULL REFERENCES ty_hr_contract_term_period(id),term_id bigint NOT NULL REFERENCES ty_hr_contract_term(id),
 parent_key text NOT NULL,resolution_key text NOT NULL,version integer NOT NULL CHECK(version>0),
 rulebook_id bigint NOT NULL REFERENCES ty_pay_config(id),pay_period date NOT NULL CHECK(extract(day FROM pay_period)=1),
 earning_from date NOT NULL,earning_to date NOT NULL CHECK(earning_to>earning_from),
 mode text NOT NULL CHECK(mode IN('input','cash')),input_key text,output_unit text NOT NULL,item_code text NOT NULL REFERENCES ty_pay_item_catalog(code),
 currency text NOT NULL CHECK(currency IN('CNY','HKD')),
 factor_numerator numeric(30,0)NOT NULL CHECK(factor_numerator>=0),factor_denominator numeric(30,0)NOT NULL CHECK(factor_denominator>0),
 manual_value numeric(20,4)CHECK(manual_value>=0),wage_tags jsonb NOT NULL DEFAULT '{}',source_hash text NOT NULL,
 evidence_ref text NOT NULL CHECK(length(btrim(evidence_ref))>=4),
 status text NOT NULL DEFAULT'draft'CHECK(status IN('draft','approved')),revision integer NOT NULL DEFAULT 1,
 created_by bigint NOT NULL REFERENCES sys_account(id),approved_by bigint REFERENCES sys_account(id),approved_at timestamptz,review_ref text,
 created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(group_id,resolution_key,version),CHECK((mode='input')=(input_key IS NOT NULL)),
 CHECK(status<>'approved'OR(approved_by IS NOT NULL AND approved_at IS NOT NULL AND length(btrim(review_ref))>=4))
);

CREATE FUNCTION fn_ty_cp_source_hash(p_period bigint)RETURNS text LANGUAGE sql STABLE SET search_path=''AS $$
 SELECT md5(jsonb_build_object('period',to_jsonb(p),'term',to_jsonb(t),'contract',to_jsonb(c),'employment',to_jsonb(e),'locale',(SELECT to_jsonb(l)FROM public.fn_ty_company_locale(c.company_id)l))::text)
 FROM public.ty_hr_contract_term_period p JOIN public.ty_hr_contract_term t ON t.id=p.term_id
 JOIN public.ty_hr_contract c ON c.id=t.contract_id JOIN public.ty_employment e ON e.id=c.employment_id WHERE p.id=p_period
$$;

CREATE FUNCTION fn_ty_cp_rule_uses(book jsonb,item text,input_key text)RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=''AS $$
 WITH RECURSIVE dependencies(name)AS(SELECT item UNION SELECT d.value FROM dependencies p JOIN jsonb_array_elements(book->'compiled'->'order')r ON r->>'code'=p.name CROSS JOIN LATERAL jsonb_array_elements_text(r->'dependencies')d)
 SELECT EXISTS(SELECT 1 FROM dependencies WHERE name=input_key)
$$;

CREATE FUNCTION fn_ty_cp_resolve(r public.ty_cp_resolution,p_approved boolean DEFAULT true)RETURNS jsonb LANGUAGE plpgsql SET search_path=''AS $$
DECLARE t public.ty_hr_contract_term%ROWTYPE;p public.ty_hr_contract_term_period%ROWTYPE;c public.ty_hr_contract%ROWTYPE;
 e public.ty_employment%ROWTYPE;b public.ty_pay_config%ROWTYPE;i public.ty_pay_item_catalog%ROWTYPE;l record;legal_start record;legal_end record;
 semantics text;expected_key text;v numeric;fraction_value jsonb;k text;tag text;treatment jsonb;
BEGIN
 SELECT*INTO p FROM public.ty_hr_contract_term_period WHERE id=r.term_period_id FOR SHARE;
 SELECT*INTO t FROM public.ty_hr_contract_term WHERE id=p.term_id FOR SHARE;
 SELECT*INTO c FROM public.ty_hr_contract WHERE id=t.contract_id FOR SHARE;
 SELECT*INTO e FROM public.ty_employment WHERE id=c.employment_id FOR SHARE;
 SELECT*INTO b FROM public.ty_pay_config WHERE id=r.rulebook_id FOR SHARE;
 SELECT*INTO i FROM public.ty_pay_item_catalog WHERE code=r.item_code;
 IF p.id IS NULL OR r.term_id<>t.id OR r.parent_key<>t.parent_key OR p.parent_key<>t.parent_key OR p.source_contract_id<>c.id
 OR ROW(r.group_id,r.company_id,r.person_id,r.employment_id)IS DISTINCT FROM ROW(c.group_id,c.company_id,c.person_id,c.employment_id)
 OR e.group_id<>c.group_id OR e.company_id<>c.company_id OR e.person_id<>c.person_id OR e.status='cancelled'
 OR c.status NOT IN('signed','terminated')OR c.evidence_file_id IS NULL OR t.status NOT IN('effective','ended')OR p.status<>'active'
 OR r.earning_from<p.valid_from OR p.valid_to IS NOT NULL AND r.earning_to>p.valid_to
 OR r.earning_from<c.starts_on OR c.ends_on IS NOT NULL AND r.earning_to>c.ends_on+1 OR c.terminated_on IS NOT NULL AND r.earning_to>c.terminated_on+1
 OR r.earning_from<e.hire_date OR e.leave_date IS NOT NULL AND r.earning_to>e.leave_date+1
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 合同给薪须沿已签已核条款、原期间与真实雇佣';END IF;
 IF lower(e.employment_type)~'(outsource|agency|vendor|派遣|外包)'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 供应商用工不得转作直营合同给薪';END IF;
 SELECT*INTO legal_start FROM public.fn_ty_hr_verified_legal_subject(e.id,r.earning_from);
 SELECT*INTO legal_end FROM public.fn_ty_hr_verified_legal_subject(e.id,r.earning_to-1);
 SELECT*INTO l FROM public.fn_ty_company_locale(c.company_id);
 IF legal_start.legal_entity_company_id IS DISTINCT FROM c.legal_entity_company_id OR legal_end.legal_entity_company_id IS DISTINCT FROM c.legal_entity_company_id
 OR legal_start.legal_subject_name IS DISTINCT FROM legal_end.legal_subject_name
 OR l.region_code IS DISTINCT FROM c.region_code OR l.currency_code IS DISTINCT FROM r.currency
 OR t.currency IS NOT NULL AND t.currency<>r.currency
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 合同给薪的法律雇主、地区或币种待核';END IF;
 IF b.kind<>'rulebook'OR b.status<>'approved'OR b.group_id<>r.group_id OR b.company_id<>r.company_id OR b.currency<>r.currency
 OR b.valid_from>r.pay_period OR b.valid_to IS NOT NULL AND b.valid_to<r.pay_period+interval'1 month'
 OR i.code IS NULL OR i.system NOT IN('COMMON',b.system)OR t.payroll_item_code IS DISTINCT FROM r.item_code
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 合同给薪工资方案、项目与期间须明确一致';END IF;
 semantics:=t.value->>'semantics';
 IF t.unit IN('month','once')AND r.factor_numerator>r.factor_denominator
 OR t.unit='day'AND r.factor_numerator>(r.earning_to-r.earning_from)*r.factor_denominator
 OR t.unit='hour'AND r.factor_numerator>(r.earning_to-r.earning_from)*24*r.factor_denominator
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 折算数量超出原单位及归属区间，不能用比例放大合同义务';END IF;
 IF semantics NOT IN('parameter','one_time_payable','recurring_payable')OR t.value->>'periodicity'NOT IN('once','monthly','hourly','daily','schedule','none')
 OR r.source_hash IS DISTINCT FROM public.fn_ty_cp_source_hash(p.id)
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 条款版本或给薪性质已变，请重新核定';END IF;
 expected_key:=CASE WHEN semantics='one_time_payable'THEN'once:'||t.parent_key ELSE'period:'||t.parent_key||':'||to_char(r.pay_period,'YYYY-MM')||':'||r.earning_from||':'||r.earning_to END;
 IF r.resolution_key<>expected_key OR r.earning_from>=r.pay_period+interval'1 month'
 OR semantics<>'one_time_payable'AND(r.earning_from<r.pay_period OR r.earning_to>r.pay_period+interval'1 month')
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 一次性义务和按期归属须分别核定，不自动猜工资采用月';END IF;
 IF semantics='one_time_payable'AND(t.unit<>'once'OR t.value->>'periodicity'<>'once'OR r.mode<>'cash')
 OR semantics='recurring_payable'AND NOT(t.unit='month'AND t.value->>'periodicity'='monthly'OR t.unit='hour'AND t.value->>'periodicity'='hourly'OR t.unit='day'AND t.value->>'periodicity'='daily')
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 合同给薪的单位、周期或条件仍待核';END IF;
 IF r.mode='cash'THEN
  IF semantics='parameter'OR t.amount IS NULL OR r.manual_value IS NOT NULL OR r.output_unit<>'currency_amount'OR i.category<>'cash_earnings'OR i.unit<>'currency_amount'
  THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 参数性质不能作为现金，现金须有原条款金额及明确工资项目';END IF;
  IF i.metadata->>'exclusion_group'='base_pay_basis_per_segment'
  THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 基薪标准须作为合同参数替代，不能增列合同现金或用奖金性质伪装';END IF;
  FOREACH k IN ARRAY ARRAY['hk_adw','cn_average','cn_annual_leave','ordinary_wage']LOOP
   tag:=r.wage_tags->>k;IF tag IS NULL OR tag NOT IN('include','exclude','not_applicable')THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 合同现金的法定工资范围须逐项有据核定';END IF;
  END LOOP;
  treatment:=b.data->'source_treatments'->'contract_terms'->r.item_code;IF treatment?'wage_tags'THEN treatment:=treatment->'wage_tags';END IF;
  IF treatment IS NULL OR NOT r.wage_tags@>treatment OR NOT treatment?'hk_adw'OR NOT treatment?'cn_average'OR NOT treatment?'cn_annual_leave'OR NOT treatment?'ordinary_wage'
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(r.wage_tags)x WHERE x NOT IN('hk_adw','cn_average','cn_annual_leave','ordinary_wage'))
  THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 合同现金工资范围须承接已核方案待遇，不可单独自标';END IF;
 ELSE
  IF semantics='one_time_payable'OR r.input_key!~'^[A-Za-z_][A-Za-z0-9_]{0,63}$'OR b.data->'inputs'->r.input_key->>'source'IS DISTINCT FROM'profile'
  OR b.data->'inputs'->r.input_key->>'unit'IS DISTINCT FROM r.output_unit
  OR t.value?'configuration_key'AND t.value->>'configuration_key'IS DISTINCT FROM coalesce(b.data->'inputs'->r.input_key->>'key',r.input_key)
  OR NOT public.fn_ty_cp_rule_uses(b.data,r.item_code,r.input_key)
  THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 合同参数须映射明确的已核规则输入及原工资项目';END IF;
 END IF;
 IF t.amount IS NULL THEN
  IF r.mode<>'input'OR r.manual_value IS NULL OR semantics<>'parameter'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 无金额参数须有明确人工核定值，不把空值作为零';END IF;v:=r.manual_value;
 ELSE
  IF r.manual_value IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 已有条款金额不能另填手工金额覆盖';END IF;v:=t.amount;
 END IF;
 fraction_value:=public.fn_ty_payroll_fraction(v*10000*r.factor_numerator,10000*r.factor_denominator);
 IF p_approved AND(r.status<>'approved'OR EXISTS(SELECT 1 FROM public.ty_cp_resolution n WHERE n.group_id=r.group_id AND n.resolution_key=r.resolution_key AND n.status='approved'AND n.version>r.version))
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 合同给薪核定尚未独立批准或已有新版本';END IF;
 RETURN jsonb_build_object('value',fraction_value,'target',public.fn_ty_payroll_money(fraction_value)::text,'semantics',semantics,'source_hash',r.source_hash,'resolution_hash',md5(to_jsonb(r)::text));
END;$$;

CREATE FUNCTION fn_ty_cp_current(p_id bigint)RETURNS jsonb LANGUAGE plpgsql SET search_path=''AS $$DECLARE r public.ty_cp_resolution%ROWTYPE;BEGIN SELECT*INTO r FROM public.ty_cp_resolution WHERE id=p_id FOR SHARE;IF r.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_NOT_FOUND: 合同给薪核定不存在';END IF;RETURN public.fn_ty_cp_resolve(r);END;$$;

CREATE FUNCTION fn_ty_cp_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$BEGIN
 IF TG_OP='DELETE'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同给薪核定保留历史，不删除';END IF;
 PERFORM id FROM public.ty_group WHERE id=NEW.group_id FOR UPDATE;
 IF TG_OP='INSERT'AND(NEW.status<>'draft'OR NEW.revision<>1 OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL OR NEW.version<>(SELECT coalesce(max(version),0)+1 FROM public.ty_cp_resolution WHERE group_id=NEW.group_id AND resolution_key=NEW.resolution_key))
 OR TG_OP='UPDATE'AND(OLD.status<>'draft'OR NEW.status<>'approved'OR NEW.revision<>OLD.revision+1)
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同给薪核定须沿新草稿及独立核准推进，已核历史不可覆写';END IF;
 IF TG_OP='UPDATE'AND(to_jsonb(NEW)-ARRAY['status','revision','approved_by','approved_at','review_ref']IS DISTINCT FROM to_jsonb(OLD)-ARRAY['status','revision','approved_by','approved_at','review_ref']OR OLD.status<>'draft'OR NEW.status<>'approved'OR NEW.revision<>OLD.revision+1)
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同给薪核定内容只追加，新核定须新版本';END IF;
 PERFORM public.fn_ty_cp_resolve(NEW,false);
 IF NEW.status='approved'AND NOT public.fn_ty_pay_distinct_reviewer(NEW.created_by,NEW.approved_by,NEW.group_id,NEW.person_id)
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='合同给薪须独立自然人且非受益人核准';END IF;
 RETURN NEW;
END;$$;
CREATE TRIGGER ty_cp_guard BEFORE INSERT OR UPDATE OR DELETE ON ty_cp_resolution FOR EACH ROW EXECUTE FUNCTION fn_ty_cp_guard();

CREATE FUNCTION fn_ty_cp_input(p_resolution bigint,p_batch bigint,p_employment bigint,p_key text,p_unit text,p_hash text)RETURNS jsonb LANGUAGE plpgsql SET search_path=''AS $$
DECLARE r public.ty_cp_resolution%ROWTYPE;b public.ty_pay_batch%ROWTYPE;v jsonb;
BEGIN SELECT*INTO r FROM public.ty_cp_resolution WHERE id=p_resolution;SELECT*INTO b FROM public.ty_pay_batch WHERE id=p_batch;v:=public.fn_ty_cp_current(r.id);
 IF r.mode<>'input'OR ROW(r.group_id,r.company_id,r.employment_id,r.rulebook_id,r.pay_period,r.input_key,r.output_unit)IS DISTINCT FROM ROW(b.group_id,b.company_id,p_employment,b.rulebook_id,b.period,p_key,p_unit)
 OR v->>'resolution_hash'IS DISTINCT FROM p_hash THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 合同参数来源、单位、人员或版本不符';END IF;
 RETURN v->'value';END;$$;

CREATE FUNCTION fn_ty_cp_inputs(refs jsonb,p_batch bigint,p_employment bigint,p_key text,p_unit text)RETURNS jsonb LANGUAGE plpgsql SET search_path=''AS $$
DECLARE b public.ty_pay_batch%ROWTYPE;e public.ty_employment%ROWTYPE;r public.ty_cp_resolution%ROWTYPE;x record;v jsonb;total jsonb:=public.fn_ty_payroll_fraction(0,1);next_day date;last_day date;item text;n integer:=0;
BEGIN SELECT*INTO b FROM public.ty_pay_batch WHERE id=p_batch;SELECT*INTO e FROM public.ty_employment WHERE id=p_employment;
 IF jsonb_typeof(refs)IS DISTINCT FROM'array'OR jsonb_array_length(refs)=0 OR jsonb_array_length(refs)>64 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 合同参数片段列表须明确且有界';END IF;
 next_day:=greatest(e.hire_date,b.period);last_day:=least(coalesce(e.leave_date+1,(b.period+interval'1 month')::date),(b.period+interval'1 month')::date);
 FOR x IN SELECT j.value,cr.earning_from FROM jsonb_array_elements(refs)j JOIN public.ty_cp_resolution cr ON cr.id=(j.value->>'id')::bigint ORDER BY cr.earning_from,cr.id LOOP
  SELECT*INTO r FROM public.ty_cp_resolution WHERE id=(x.value->>'id')::bigint;
  v:=public.fn_ty_cp_input(r.id,p_batch,p_employment,p_key,p_unit,x.value->>'hash');
  IF r.earning_from<>next_day OR item IS NOT NULL AND item<>r.item_code THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 合同参数片段有重叠、缺口或项目不一致，不能猜前段标准';END IF;
  next_day:=r.earning_to;item:=r.item_code;
  n:=n+1;
  total:=public.fn_ty_payroll_fraction((total->>'n')::numeric*(v->>'d')::numeric+(v->>'n')::numeric*(total->>'d')::numeric,(total->>'d')::numeric*(v->>'d')::numeric);
 END LOOP;
 IF next_day<>last_day OR n<>jsonb_array_length(refs)THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 合同参数未覆盖本雇佣完整给薪期间或引用缺失，须补齐有据片段';END IF;
 RETURN total;
END;$$;

CREATE FUNCTION fn_ty_cp_pay_key(p_batch bigint,p_adoption bigint)RETURNS text LANGUAGE plpgsql SET search_path=''AS $$
DECLARE a public.ty_pay_adoption%ROWTYPE;b public.ty_pay_batch%ROWTYPE;r public.ty_cp_resolution%ROWTYPE;o public.ty_pay_obligation%ROWTYPE;i public.ty_pay_item%ROWTYPE;rc public.ty_pay_config%ROWTYPE;v jsonb;
BEGIN
 SELECT*INTO a FROM public.ty_pay_adoption WHERE id=p_adoption;SELECT*INTO b FROM public.ty_pay_batch WHERE id=p_batch;
 SELECT*INTO r FROM public.ty_cp_resolution WHERE id=a.source_id::bigint;SELECT*INTO o FROM public.ty_pay_obligation WHERE id=a.obligation_id;
 SELECT*INTO i FROM public.ty_pay_item WHERE adoption_id=a.id;SELECT c.*INTO rc FROM public.ty_pay_row pr JOIN public.ty_pay_config c ON c.id=pr.relationship_config_id WHERE pr.id=i.row_id;
 v:=public.fn_ty_cp_current(r.id);
 IF a.source_domain<>'contract_terms'OR a.batch_id<>b.id OR r.mode<>'cash'OR ROW(r.group_id,r.company_id,r.person_id,r.employment_id,r.rulebook_id,r.pay_period,r.currency,r.item_code)IS DISTINCT FROM ROW(b.group_id,b.company_id,o.person_id,o.employment_id,b.rulebook_id,b.period,b.currency,i.code)
 OR a.source_revision<>(r.version||':'||r.revision)OR a.source_hash IS DISTINCT FROM v->>'resolution_hash'OR NOT i.wage_tags@>r.wage_tags
 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 合同现金须反查同人同期间同项目的已核来源';END IF;
 IF v->>'semantics'='one_time_payable'THEN
  IF EXISTS(SELECT 1 FROM public.ty_pay_adoption x JOIN public.ty_pay_item it ON it.adoption_id=x.id JOIN public.ty_pay_row pr ON pr.id=it.row_id JOIN public.ty_pay_batch pb ON pb.id=x.batch_id WHERE x.source_domain='payroll_calculation'AND x.state IN('reserved','confirmed')AND pb.period=b.period AND pr.employment_id=r.employment_id AND it.code=r.item_code)
  THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 一次性合同义务存在同项档案工资，须先有据核对覆盖，不能叠加';END IF;
  RETURN'contract_once:'||(rc.data->>'actual_relationship_key')||':'||r.parent_key;
 END IF;
 RETURN public.fn_ty_pay_component_key(b.group_id,b.company_id,r.employment_id,r.person_id,rc.data->>'actual_relationship_key',b.period,r.item_code,o.purpose);
END;$$;
CREATE FUNCTION fn_ty_cp_pay_expected(p_batch bigint,p_adoption bigint)RETURNS numeric LANGUAGE plpgsql SET search_path=''AS $$DECLARE a public.ty_pay_adoption%ROWTYPE;v jsonb;BEGIN PERFORM public.fn_ty_cp_pay_key(p_batch,p_adoption);SELECT*INTO a FROM public.ty_pay_adoption WHERE id=p_adoption;v:=public.fn_ty_cp_current(a.source_id::bigint);RETURN(v->>'target')::numeric;END;$$;
ALTER FUNCTION fn_ty_pay_extension_expected(bigint,bigint)RENAME TO fn_ty_pay_extension_expected_pre235;
ALTER FUNCTION fn_ty_pay_extension_key(bigint,bigint)RENAME TO fn_ty_pay_extension_key_pre235;
CREATE FUNCTION fn_ty_pay_extension_expected(p_batch bigint,p_adoption bigint)RETURNS numeric LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF EXISTS(SELECT 1 FROM public.ty_pay_adoption WHERE id=p_adoption AND source_domain='contract_terms')THEN RETURN public.fn_ty_cp_pay_expected(p_batch,p_adoption);END IF;RETURN public.fn_ty_pay_extension_expected_pre235(p_batch,p_adoption);END;$$;
CREATE FUNCTION fn_ty_pay_extension_key(p_batch bigint,p_adoption bigint)RETURNS text LANGUAGE plpgsql SET search_path=''AS $$BEGIN IF EXISTS(SELECT 1 FROM public.ty_pay_adoption WHERE id=p_adoption AND source_domain='contract_terms')THEN RETURN public.fn_ty_cp_pay_key(p_batch,p_adoption);END IF;RETURN public.fn_ty_pay_extension_key_pre235(p_batch,p_adoption);END;$$;
-- Exact installed dispatch is extended, preserving234 when installed. No guard
-- is replaced with a weaker client amount check.
DO $$DECLARE f text;d text;needle text;old_input text;new_input text;
BEGIN
 FOREACH f IN ARRAY ARRAY['fn_ty_pay_authority_guard()','fn_ty_pay_reverse_provenance()']LOOP
  SELECT pg_get_functiondef(('public.'||f)::regprocedure)INTO d;
  needle:=CASE WHEN strpos(d,'IN(''statutory_calculation'',''performance_award'',''training_award'',''leave_pay'')')>0 THEN'IN(''statutory_calculation'',''performance_award'',''training_award'',''leave_pay'')'ELSE'IN(''statutory_calculation'',''performance_award'',''training_award'')'END;
  IF strpos(d,needle)=0 THEN RAISE EXCEPTION '235 prerequisite payroll dispatch drifted';END IF;
  d:=replace(d,needle,left(needle,length(needle)-1)||',''contract_terms'')');
  IF f='fn_ty_pay_authority_guard()'THEN
   old_input:='v:=p.data->''parameters''->coalesce(entry.value->>''key'',entry.key);';
   new_input:='v:=CASE WHEN a.source_snapshot->''contract_parameters'' ? entry.key THEN jsonb_build_object(''unit'',entry.value->>''unit'',''value'',public.fn_ty_cp_inputs(a.source_snapshot->''contract_parameters''->entry.key,NEW.id,r.employment_id,entry.key,entry.value->>''unit''))ELSE p.data->''parameters''->coalesce(entry.value->>''key'',entry.key)END;';
   IF strpos(d,old_input)=0 THEN RAISE EXCEPTION '235 prerequisite profile input resolver drifted';END IF;d:=replace(d,old_input,new_input);
  END IF;
  EXECUTE d;
 END LOOP;
END$$;

CREATE FUNCTION fn_ty_cp_required(p_batch bigint,p_employment bigint,refs jsonb,cash_ids jsonb DEFAULT '[]')RETURNS void LANGUAGE plpgsql SET search_path=''AS $$
DECLARE b public.ty_pay_batch%ROWTYPE;required record;given record;book public.ty_pay_config%ROWTYPE;resolved public.ty_cp_resolution%ROWTYPE;v jsonb;paid numeric;
BEGIN SELECT*INTO b FROM public.ty_pay_batch WHERE id=p_batch;SELECT*INTO book FROM public.ty_pay_config WHERE id=b.rulebook_id;
 FOR given IN SELECT*FROM jsonb_each(coalesce(refs,'{}'::jsonb))LOOP
  IF book.data->'inputs'->given.key->>'source'IS DISTINCT FROM'profile'THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_ARGUMENT: 合同参数不得夹带未登记输入';END IF;
  PERFORM public.fn_ty_cp_inputs(given.value,p_batch,p_employment,given.key,book.data->'inputs'->given.key->>'unit');
 END LOOP;
 FOR required IN SELECT p.id,t.parent_key,t.value->>'semantics' semantics FROM public.ty_hr_contract_term_period p JOIN public.ty_hr_contract_term t ON t.id=p.term_id JOIN public.ty_hr_contract c ON c.id=t.contract_id
 WHERE c.employment_id=p_employment AND c.starts_on<b.period+interval'1 month'AND(c.ends_on IS NULL OR c.ends_on>=b.period)AND(c.terminated_on IS NULL OR c.terminated_on>=b.period)AND c.status IN('signed','terminated')AND t.status IN('effective','ended')AND p.status='active'AND p.valid_from<b.period+interval'1 month'AND(p.valid_to IS NULL OR p.valid_to>b.period)
 AND(t.value->>'semantics'='parameter'AND(t.amount IS NOT NULL OR t.value?'configuration_key')OR t.value->>'semantics'='recurring_payable'OR t.value->>'semantics'='one_time_payable'AND EXISTS(SELECT 1 FROM public.ty_cp_resolution cr WHERE cr.term_period_id=p.id AND cr.pay_period=b.period AND cr.status='approved'AND NOT EXISTS(SELECT 1 FROM public.ty_cp_resolution n WHERE n.group_id=cr.group_id AND n.resolution_key=cr.resolution_key AND n.status='approved'AND n.version>cr.version)))LOOP
  IF EXISTS(SELECT 1 FROM jsonb_each(coalesce(refs,'{}'::jsonb))k CROSS JOIN LATERAL jsonb_array_elements(k.value)v JOIN public.ty_cp_resolution r ON r.id=(v.value->>'id')::bigint WHERE r.term_period_id=required.id)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(cash_ids)j JOIN public.ty_cp_resolution r ON r.id::text=j.value WHERE r.term_period_id=required.id AND r.employment_id=p_employment AND r.mode='cash')THEN CONTINUE;END IF;
  -- Only an independently reviewed current cash target with an already equal
  -- confirmed contract obligation is covered. Profile cash is not inferred.
  SELECT cr.*INTO resolved FROM public.ty_cp_resolution cr WHERE cr.term_period_id=required.id AND cr.pay_period=b.period AND cr.mode='cash'AND cr.status='approved'AND cr.source_hash=public.fn_ty_cp_source_hash(required.id)
  AND NOT EXISTS(SELECT 1 FROM public.ty_cp_resolution newer WHERE newer.group_id=cr.group_id AND newer.resolution_key=cr.resolution_key AND newer.status='approved'AND newer.version>cr.version)ORDER BY cr.id DESC LIMIT 1;
  IF resolved.id IS NOT NULL THEN
   v:=public.fn_ty_cp_current(resolved.id);
   SELECT coalesce(sum(a.delta),0)INTO paid FROM public.ty_pay_adoption a JOIN public.ty_cp_resolution hist ON a.source_domain='contract_terms'AND a.source_id=hist.id::text WHERE hist.employment_id=p_employment AND hist.parent_key=required.parent_key AND a.state='confirmed'AND(required.semantics='one_time_payable'OR hist.pay_period=b.period);
   IF paid=(v->>'target')::numeric THEN CONTINUE;END IF;
  END IF;
  RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='E_TY_CONFLICT: 已生效合同给薪未核定并明确采用，不能漏选后继续沿旧档案或静默少付';
 END LOOP;
END;$$;
CREATE FUNCTION fn_ty_cp_confirm_guard()RETURNS trigger LANGUAGE plpgsql SET search_path=''AS $$DECLARE x record;BEGIN
 IF NEW.status<>'confirmed'OR OLD.status='confirmed'THEN RETURN NEW;END IF;
 FOR x IN SELECT a.source_snapshot,r.employment_id FROM public.ty_pay_adoption a JOIN public.ty_pay_item i ON i.adoption_id=a.id JOIN public.ty_pay_row r ON r.id=i.row_id WHERE a.batch_id=NEW.id AND a.source_domain='payroll_calculation'LOOP
  PERFORM public.fn_ty_cp_required(NEW.id,x.employment_id,x.source_snapshot->'contract_parameters',(SELECT coalesce(jsonb_agg(a.source_id),'[]'::jsonb)FROM public.ty_pay_adoption a WHERE a.batch_id=NEW.id AND a.source_domain='contract_terms'));
 END LOOP;RETURN NEW;END;$$;
CREATE TRIGGER ty_cp_confirm_guard BEFORE UPDATE ON ty_pay_batch FOR EACH ROW EXECUTE FUNCTION fn_ty_cp_confirm_guard();
